import{c as e}from"./DQIURQBV.js";const a={lang:"en",meta:{title:`${e.brand} — an AI expert for businesses and for individuals`,description:`${e.brand} is a Berlin company that puts a senior AI expert on your side. For businesses: consulting inside the company, the team enabled, and the platforms built, with every decision staying with your leadership. For individuals: a straight answer about what AI can do for your decision, your idea or your skills, and help using it yourself. The first conversation is free.`},nav:{contact:"Contact",menu:"Menu",sections:["Who we help","How we work","Examples","Who we are","Contact"],theme:"Switch colour theme",themeLight:"Light",themeDark:"Dark"},hero:{headline:"An AI expert on your side.",subline:`${e.brand} puts a senior AI expert at the table of the people who need one. For a company, a team or a research group, that means finding where AI changes what you can do, proving it in your own operation, and leading it for as long as it pays off. For one person, it means a straight answer about your decision, your idea or your skills, and help using AI yourself. Either way, every decision stays with you.`,button:"Book a 30-minute call"},doors:{eyebrow:"Who we help",title:"Two doors. One way of working.",business:{label:"For businesses",title:"You run something.",text:"A company, a startup, a department, a practice, a research group — anything with people, work and someone who decides. You can see AI changing your field, you have no room for an AI department, and you want a straight answer about what it does for you. We become your AI expert: consulting to start, the Head of AI role for as long as it pays off.",cta:"How we work with businesses"},individual:{label:"For individuals",title:"You are one person with a question.",text:"You do not need a company to need an AI expert. A decision with a lot of money in it, a company you are about to start, an idea you cannot judge yet, a skill you want, a child who will grow up with all of this. You bring the question; we bring what AI can and cannot do about it, in plain language, and help you use it yourself.",cta:"How we work with individuals"}},agents:{eyebrow:"What we do",title:"AI that works when nobody is watching.",lede:"Most businesses meet AI as a chat window somebody remembers to open. That is the smallest version of it. What we build works on its own, on your own material, for everyone whose work touches it — and the first job is finding where that is worth doing in your business.",items:[{title:"It runs in the background.",text:"Not a tool your people have to remember. Work that used to wait for someone to have a free hour happens continuously, on your own systems, and what it produces is waiting when your team arrives."},{title:"It serves the whole team, not one person.",text:"One system, used by everyone whose work touches the same material. What one person works out about how to use it, everybody gets. That is the difference between buying licences and having a capability."},{title:"It explores what you have no time to explore.",text:"The version of the question you would ask if you had a spare week: the market nobody checked, the seven offers nobody compared, the option that was never on the table. You get the options and the reasoning behind them. You still choose."},{title:"It changes what you can sell, not only what you can finish.",text:"Some of what we find makes an existing week shorter. Some of it becomes a service you could not have offered last year. We test both in your own operation, with your own data, before you commit to either."}]},studio:{worksLabel:"Real examples",capabilitiesLabel:"How it works",bookLabel:"Book a call",bookTitle:"Pick a time that suits you.",bookNote:"Thirty minutes, free, no preparation needed.",workBack:"All examples",worksHeading:"What AI already does inside teams like yours.",worksIntro:"Every example here is something we designed and ran ourselves, inside a real business or team with real deadlines. Each one shows what changed, what stayed with the people, and where we drew the line. Pick the one closest to your work.",worksMeta:`Real examples of AI inside businesses, startups and research groups: startups, company departments, research groups, architecture practices, law firms, marketing agencies, real estate and non-profits. Set up by ${e.brand}, AI consulting in Berlin.`,workName:"Who it is for",workCovers:"What it takes over",workMachinery:"What the system takes over",workJudgement:"What stays with you",workBuilds:"What we build",workStops:"Where it stops",workProof:"How you see it working",workRefuse:"When we say no",workCost:"What it asks of you",bookCta:"Or write to us",close:"Close"},who:{rosterTitle:"Where we have already worked.",roster:{executives:"Founders & Directors","team-leaders":"Heads of Department",research:"Research Groups",architects:"Architecture","marketing-agencies":"Marketing Agencies",lawyers:"Law Firms","estate-agents":"Real Estate","volunteer-orgs":"NGOs & Non-Profits"},individuals:{"job-seekers":"Job seekers",athletes:"Athletes","home-buyers":"Home buyers",teachers:"Teachers",coaches:"Coaches & yoga teachers","online-shoppers":"Online shoppers"},notListed:"A sector we have never worked in? The work runs the same way, and you hear early if it does not. Ask us."},method:{label:"How we decide what to build",title:`How we decide what to build — ${e.brand}`,metaDescription:"One question decides everything: which part of your week is repetitive work, and which part needs your judgement? The four tests we use, the four phases of every project, and the five reasons we say no.",headline:"Which part of your week repeats, and which part needs you?",intro:["Every person we have worked with arrived with a different job title and the same sentence: one part of my week has become unbearable. The profession changes. The shape of the problem almost never does.","We do not ask what you want automated, because almost nobody knows. You know what hurts. Our job is to find the exact line between the work that repeats and the work that needs your judgement, and to build only on the repetitive side of it. Finding that line is the hard part. Building the tool is the easy part."],testsTitle:"How we tell one from the other.",machineryLabel:"Repetitive work — all four must be true",machinery:["It repeats. More than once a week, in roughly the same shape.","It follows rules. If you had to explain how you do it, you could, in sentences rather than gestures.","It is easy to check. A wrong result is obviously wrong to you within seconds.","A caught mistake costs little. If the tool gets it wrong and you notice, you lose a minute, nothing more."],judgementLabel:"Your judgement — any one is enough",judgement:["You are liable for it. Your name, licence or signature is on it.","Your taste is the product. People pay you precisely because the view is yours.","The relationship is the product. A patient, a student, a client, a reader.","It is a real decision under uncertainty, not a lookup with extra steps."],seam:"We build up to that line and never across it. Nearly every failed AI project we have been asked to rescue failed because someone built across the line, and the person quietly stopped trusting the results.",refuseTitle:"When we say no.",refuseIntro:"We say no out loud, and we keep the relationship. Saying no is most of the reason clients introduce us to other owners.",refuse:[{title:"There is too little of it.",text:"Under roughly an hour a week, keeping a tool running costs more than the task itself."},{title:"Every case is different.",text:"If no two instances look alike, there is nothing repetitive to take over. There is only skill, and skill is not a bottleneck to remove."},{title:"One mistake would be too expensive.",text:"If a single wrong result could end a career, the tool prepares the material and does nothing else."},{title:"A simple tool already exists.",text:"A calendar, a form, a shared spreadsheet, a template. We set that up, say so, and move on."},{title:"It is a decision, not a workload.",text:"Some people do not need a system. They need to decide something they have been avoiding. No software fixes that."}],registersTitle:"Two kinds of experience.",registersText:`Two registers, on purpose. Years of professional engineering behind us, building production AI systems that other people depend on inside large organisations — that work teaches us what survives audits, handovers and colleagues who never asked for the tool. And at ${e.brand}, we sit at the table of an owner-led firm or a research group, which keeps us direct: one room, one decision-maker, no committee.`,casesCta:"See the real examples",teamCta:"How we join your team"},built:{items:[{slug:"lawyers",title:`AI for lawyers: the firm’s own positions, applied to every draft — ${e.brand}`,metaDescription:"Every contract the firm has touched held as one current object, every deadline buried inside them in your diary, and each incoming draft measured against the positions your firm actually holds. No accept-all button.",label:"Lawyers",headline:"The firm’s own positions, applied to every draft that arrives.",story:["A two-partner commercial firm. An in-house department of five. Three solo Rechtsanwälte. A general counsel who is the entire legal function of a 300-person company. They are not behind on law. They are behind on contracts as objects — files that arrive, move, change and get lost.","A contract arrives as an attachment called Vertrag_final_final_v3(2).docx. Somebody replies with tracked changes from a version that was already superseded. Three weeks later a deadline that lived only in that document passes unnoticed. Nobody can say which version was signed. The lawyer spends the evening doing archival work with a law degree."],machinery:["Holding every contract the firm has touched as one current object — every version, every counterparty, every predecessor, permanently","Extracting the facts that carry risk: parties, dates, term, notice periods, governing law, liability caps, auto-renewal — each one pinned to the page it came from","The deadline diary — every date buried inside every contract, in front of you before it matters","Measuring each incoming draft against the positions the firm actually holds, and marking every departure with its reason","Keeping the negotiation moving: who owes a draft, who owes a signature, and how long it has been sitting there",'Answering "where is this contract, which version is current, and what did we agree" instantly, for anyone in the firm'],judgement:["Whether a clause is acceptable","What to concede","Advice","Signature"],builds:[{name:"The contract record",text:"One place where every contract the firm has touched exists as a current object rather than as a file somebody has a copy of: identified, versioned, linked to its matter and its predecessor, wherever it arrived from. The final_final_v3(2) problem disappears in week one, and it is the change people notice first."},{name:"The contract summary sheet",text:"One structured record per contract. Every field carries a pin back to the exact page and paragraph it came from. Nothing is stated without a location, because a fact you cannot check is worse than no fact — it looks like knowledge."},{name:"The playbook comparison",text:"The firm’s positions, written down once, properly. This is the hardest and most valuable week of the project, because most firms have never written theirs down. Then each incoming draft is marked against it."},{name:"The first-pass markup",text:"The centre of the system. A Word document with tracked changes where every single suggestion carries its reason as a comment: which playbook position it comes from, or which risk it addresses. You open it in Word — your own tool, not ours — and accept or reject each one by hand."},{name:"The deadline diary",text:"Every date pulled into your calendar with reminders that escalate as it approaches. This is the piece with the highest raw value, because a missed notice period is a claim."}],stops:{title:"No legal judgement, ever, and no output leaves the building unread.",text:['No advice, to anyone, at any point, internal or external. No automatic sending to a counterparty. No clause redrafted without a stated reason you can evaluate. Every extracted fact pinned to its source so checking it takes four seconds. There is no "accept all" — we were asked to build one and refused.','Alongside that, the conditions that make it usable at all in Germany: an AV-Vertrag under Art. 28 DSGVO, a separate confidentiality undertaking in Textform under §43e BRAO with express instruction on §203 StGB, data kept in the EU, no training on client content, privilege preserved, a full audit trail, and a documented answer to the Kammer question "who did this and can you show me?" A legal AI system without an audit trail is not deployable, whatever else it can do.']},proof:'Missed notice periods since the deadline diary went live: none so far. "What did we agree, and which version is current" answered in seconds rather than in an afternoon. The share of incoming drafts that reach a partner already measured against the firm’s positions. And the one the partners cite — evenings no longer spent on version archaeology.',refuse:"Bespoke, high-value, one-off negotiation work. There is no playbook there because there is no repetition, and a first-pass markup on a genuinely novel deal is noise dressed up as help.",cost:"Two weeks of your time writing the playbook down with us — the positions your firm actually holds, not the ones it assumes it holds. After that, about eleven minutes per contract instead of forty, spent reading suggestions rather than hunting for versions.",quotes:[{text:"The version problem alone was costing us evenings — Vertrag_final_final_v3 and nobody able to say which one was signed. He shipped only the intake and the filing in the first month and then stopped, which I found strange until I understood it was deliberate. The markup came later and every single suggestion arrives in Word with a reason attached, and I accept or reject each one myself. He was asked for an accept-all button and refused, and I would not have kept working with him if he had built it.",name:"Partner, commercial practice"},{text:"We are five people doing the legal work of a three-hundred-person company. What changed my week is the diary — every notice period in every contract is now a date I will be told about, and before this we had missed one and it was expensive. The extraction pins every field back to the page it came from, so checking it takes four seconds rather than trusting it. The audit trail was non-negotiable for us and it was the first thing he asked about, not the last.",name:"General counsel, manufacturing, ~300 staff"}]},{slug:"architects",title:`AI for architects: paperwork done the same day — ${e.brand}`,metaDescription:"A drawing register that knows the current revision, seven contractor quotes in one comparison with gaps flagged, and site Protokolle done the same evening. It never designs.",label:"Architects",headline:"The paperwork gets done the same day. The design and the compliance call stay with you.",story:["A two-person Architekturbüro doing residential conversions, a sole practitioner mostly on Bauanträge and Umbauten, and a mid-size office where one partner handles all Ausschreibung and Vergabe. All three trained for years to design, and all three spend most of their week on the paperwork that surrounds design.","For one it is the drawing register: which revision went to whom, and whether the Statiker has the current version. For another it is the Angebotsvergleich: seven contractor quotes in seven formats, compared line by line in Excel over a weekend. For the third it is the Baustellenprotokoll: forty site photos, an hour of notes, and a document that has to be written the same evening or it will not be written at all."],machinery:["Knowing at any moment which revision of which drawing is current, and who is holding which one","Checking a submission package against the authority’s own completeness list before it leaves the office","Putting every contractor’s quote into one comparable table, position by position, with the gaps marked as gaps rather than as zeros","Turning what you saw and said on site into the dated Protokoll, photos referenced and deadlines pulled out","Carrying the open actions out of every Protokoll and keeping the people responsible aware of them","Finding the governing passage in DIN, LBO, GEG or the Bebauungsplan, with its citation, never a paraphrase","Holding every date the practice is exposed to: Einwendungsfristen, Nachtragsfristen, Gewährleistung"],judgement:["The design","Whether a solution is buildable and good","Whether a quote is credible, not merely the cheapest","Whether something complies"],builds:[{name:"The drawing register",text:"Every drawing, every revision, who received what and when. Small and unglamorous, and it removes a recurring worry: “does the Statiker have rev C” becomes a two-second question with an answer you can show."},{name:"The quote comparison",text:"Seven PDFs in, one comparison out, position by position. Unpriced items are flagged as gaps, not counted as zeros. That is the real trap in an Angebotsvergleich: the cheapest quote is very often the one that left something out. The tool flags. It does not decide."},{name:"The same-evening site Protokoll",text:"On site you photograph and talk. That evening the Protokoll exists: dated, with photos referenced, defects listed, responsibilities assigned and deadlines pulled into a reminder list. The document that used to be written at 22:00 or not at all now needs fifteen minutes of editing."},{name:"The standards finder",text:"Searches your own library of standards and the Bebauungsplan and returns the passage with its citation. It looks things up. It never paraphrases a norm, because a paraphrased norm is a liability."},{name:"The completeness check",text:"Before submission, against the authority’s own list. It catches the missing Nachweis before the Bauamt does, which saves weeks."}],stops:{title:"No generated plans, and never the sentence “this complies”.",text:["No massing suggestions, no layout proposals. Not because software cannot produce something plan-shaped, but because the architect’s stamp carries liability and the design is the entire value of the practice. A design produced by software and signed by a human is the worst of both.","On compliance it finds the norm and never rules on it. The sentence it may output is “§34 BauGB, paragraph 2, may apply here — check.” The sentence it may never output is “this complies.”"]},proof:"Protokolle written the same day: near 100%. Hours per Angebotsvergleich: a weekend becomes about two hours. Submissions returned incomplete since the check went in: none so far. Time to answer “which revision is current”.",refuse:"When a practice wants generative design tools. That is a different profession from ours and, for a three-person office doing conversions, it solves a problem they do not have while adding liability they cannot carry.",cost:"Talking on site instead of writing at night. You photograph and dictate while you are there, and you spend fifteen minutes that evening editing the Protokoll instead of two hours writing it.",quotes:[{text:"The Protokoll used to be written at ten at night or not at all, and “not at all” was winning. I photograph and talk on site now, and the same evening the document exists with the photos referenced and the deadlines pulled out. Fifteen minutes of editing instead of two hours of writing. He adopted our folder structure rather than imposing his own, which sounds small and meant we actually kept using it.",name:"Architekt, sole practice"},{text:"Angebotsvergleich was a weekend. Seven quotes in seven formats and I did it in Excel by hand and I was always afraid of missing something. It normalises them by position and flags the unpriced items as gaps rather than as zeros, which is the actual trap — the cheapest quote is usually the one that left something out. It flags and it does not conclude. Two hours now, and the judgement is still mine.",name:"Partner, Architekturbüro, ~14 staff"}]},{slug:"team-leaders",title:`AI for team leaders: nothing you noticed gets forgotten — ${e.brand}`,metaDescription:"Everything you notice about your team held in one private record you own, so feedback is specific and a review is assembled rather than remembered. It never rates, ranks or monitors anyone.",label:"Team leaders",headline:"It remembers what you noticed. It never rates anyone.",story:["One leads eleven people in an engineering organisation, one leads six in customer operations. Both were promoted for being excellent at the job they no longer do, neither was given any training, and both are quietly drowning in the paperwork that comes with managing people.","Preparation, or rather the lack of it. Eleven one-to-one meetings a fortnight, each of which should begin with “last time you said X, how did that go?” and instead begins with the leader silently trying to remember. Then the writing: feedback that needs to be specific and therefore needs evidence, evidence that lives in scattered memory, and twice a year the review cycle, which eats two full weekends."],machinery:["Holding everything you have noticed about your team in one private record you own: what was said, what was agreed, what is still open","Making sure every conversation starts where the last one ended, rather than with both people trying to remember","Turning what you observed into feedback specific enough to land: the situation, what the person did, what effect it had","Keeping track of what you delegated and what became of it","Showing you where your time actually goes, against where you believe it goes","Assembling a year of your own observations when a review comes round, instead of reconstructing it in November","Writing down how the team actually works, so it survives the next person who joins"],judgement:["The assessment of a person","What is really going on with someone","Who gets promoted, who gets the hard conversation","The relationship, which is the whole job"],builds:[{name:"The person record",text:"One private file per team member, held by you: what they said they would do, what happened, and your own dated observations. Ninety seconds of dictation after each one-to-one. It is the entire system, and it changes the quality of your management more than anything else we build, because specificity is the difference between feedback that lands and feedback that does not."},{name:"Every conversation starts where the last one ended",text:"Before each one-to-one: last time’s agreements, their status, what is still open, what you said you would follow up on. Thirty seconds of reading replaces four minutes of remembering badly, and the person across the table can tell which one happened."},{name:"The feedback drafter",text:"You write “Tuesday, the deploy, handled it well.” It returns one specific paragraph — the situation, what the person did, what effect it had — built from that note and nothing else. You edit it and deliver it in person."},{name:"Where your time actually went",text:"Once a month, the difference between where you believe your week goes and where it went. Both leaders were shocked. One discovered that 8% of their time went to their team and 44% to meetings they had never once questioned attending."},{name:"The review assembler",text:"At review time, the year’s notes per person, organised. Two weekends become an afternoon, and the reviews are far more specific because they are built from notes written at the time rather than from what you happen to remember."}],stops:{title:"No assessment of a person is ever generated, and nobody is measured by the tool.",text:["It never rates, never ranks, never predicts who might leave, never suggests who is underperforming, never writes the conclusion of a review. A performance judgement produced by software and signed by a manager is a lie that somebody’s career is then built on.","It also never reaches into anyone’s work. No counting of code changes, no tickets per person, no message analysis, no activity monitoring. Both leaders had access to tools that would do this, and we recommended neither. Surveillance changes what a team tells you long before it changes what they do, and then you are blind in a way you cannot detect. The person records are your own notes about employees, so DSGVO rights apply, including the right of access — write nothing you would not show the person."]},proof:"One-to-ones that begin with a follow-up rather than a blank: from occasional to standard. Time spent on review season. The share of your week actually spent with the team. And whether feedback got specific, which the team notices before you do.",refuse:"When a leader wants visibility into what their team is doing all day. That is a trust problem, and tooling makes it worse. We say so, and we have had that conversation both times.",cost:"Ninety seconds of dictation after every conversation.",quotes:[{text:"I was promoted for being good at a job I no longer do and nobody trained me for this one. Ninety seconds of dictation after every 1:1 and now each conversation starts with “last time you said X, how did that go” instead of me silently trying to remember. My team noticed before I did. Review season went from two weekends to an afternoon and the reviews are far more specific, because they are built from notes I wrote at the time rather than from what I can recall in November.",name:"Engineering team lead, eleven reports"},{text:"The calendar audit was unpleasant. Eight per cent of my time went to my team and forty-four per cent to meetings I had never once questioned attending. I asked whether we could add visibility into what people were actually working on and he said no, and told me it was a trust problem that tooling would make worse. That was not what I wanted to hear and it was the most useful thing anyone said to me that year.",name:"Head of customer operations, six reports"}]},{slug:"estate-agents",title:`AI for estate agents: answer real buyers first — ${e.brand}`,metaDescription:"Every enquiry answered within minutes and sorted by quality, Exposés built with the Pflichtangaben checked, owners updated weekly. No valuation, no generated photos.",label:"Estate agents",headline:"Answer the eight real buyers first, not all ninety.",story:["One independent Makler in Berlin, and a two-person agency doing residential sales and some rentals. They came with opposite problems: one drowning in leads he could not answer fast enough, one struggling to produce Exposés quickly enough to win the mandate.","A listing goes live and 90 enquiries arrive in 48 hours. Perhaps eight are qualified buyers. The agent answers them in the order they arrived, at 22:00, badly, and has lost the good ones on day one. Around that: the Exposé rebuilt from scratch every time, the viewing schedule put together by hand, and the follow-ups after viewings that never get sent."],machinery:["Qualifying every enquiry the moment it arrives: complete, financing indicated, requirements matched against the property","Making sure no serious buyer waits — the acknowledgement and the qualifying questions go out in minutes rather than the next evening","Holding the whole pipeline for every property: who has viewed, who was followed up, who went quiet and when","Assembling the Exposé from the property’s own data: photos, floor plan, Energieausweis, Provision statement, Pflichtangaben","Keeping the owner informed without being asked, with comparable listings and time on market","Knowing which of your listings is going stale before the owner rings to ask about it"],judgement:["Valuation and pricing strategy","Which buyer to recommend to a seller","How to advise an owner with an unrealistic expectation","Negotiation"],builds:[{name:"Enquiry sorting",text:"Every enquiry is acknowledged within minutes, with the qualifying questions attached. The replies are sorted into qualified, incomplete and unsuitable. You then spend your attention on eight people rather than ninety. Response time is the single largest factor in who wins the buyer, and it is pure routine."},{name:"Nobody good loses a slot",text:"Qualified buyers reach your real availability without a round of messages, and the slots that get held are held by people who turn up. No-shows fell by more than half, which matters because a no-show at a block viewing costs a slot a real buyer wanted."},{name:"Exposé assembly",text:"Property data in, compliant document out — with the Pflichtangaben checked, because a missing Energieausweis figure is a fineable offence under GEG and exactly the kind of thing a tired agent forgets on a Friday. It also produces the portal versions in the right formats."},{name:"Description draft",text:"Written from the property’s actual attributes, in your voice, with no invented features. Estate agent copy has a deserved reputation and we are not adding to it — if the system has no data for a claim, it does not make the claim."},{name:"Weekly owner update",text:"Weekly, automatic, factual: enquiries, viewings, feedback themes. Both agents said this reduced anxious owner calls more than anything else, because most owner calls are requests for reassurance that nothing is happening without them."}],stops:{title:"No valuation, and nothing that misrepresents a property.",text:["Valuation is where your professional judgement and your reputation live, and it is the number the whole relationship turns on. The system can gather comparables and show time on market. It does not produce a price.","On representation: no generated images, no removing anything from a photograph, no “cosy” for tiny, no invented Baujahr, no omitted Pflichtangaben. Beyond the legal exposure, everything invented in an Exposé is discovered at the viewing — and then you are the person who wrote it. The system also never negotiates and never talks to a buyer about price."]},proof:"Minutes to first response — from hours to under five. Qualified leads per listing. Viewing no-show rate. Days on market. Owner calls per week, going down.",refuse:"Any request for automated valuation or generated property photography. Also any request to auto-reply to buyers in a way that implies a human is answering. If a buyer is talking to a system, they should be able to tell.",cost:"Answering eight good enquiries with care instead of scrolling through ninety. Filling in the property data once, properly, so the Exposé and the description have something true to work from.",quotes:[{text:"Ninety enquiries in forty-eight hours, eight of them real, and I was answering them in arrival order at ten at night and losing the good ones on day one. Everything is acknowledged within minutes now with the qualifying questions attached, and I spend my attention on the eight. Response time decides who gets the buyer and it is completely mechanical, which is apparently the point he makes to everyone.",name:"Independent Makler, Berlin"},{text:"The Exposé assembler checks the Pflichtangaben, and the missing Energieausweis figure on a Friday afternoon is exactly the mistake I have made before. It writes from the property’s actual attributes and will not invent a feature, which given the reputation of my profession I regard as a competitive advantage rather than a restriction. The weekly owner update cut the anxious phone calls more than anything else.",name:"Two-person agency, residential sales"}]},{slug:"executives",title:`AI for founder-CEOs: nothing important lives only in your head — ${e.brand}`,metaDescription:"Every commitment, relationship and number the company runs on, held in one place and kept current in the background, so decisions are made on what is known rather than on what was in the room. It never decides, never advises and never writes as you.",label:"Executives",headline:"Nothing the company agreed to sits only in somebody’s memory.",story:["The founder-CEO of a company of about 90 people. Not a corporate chief executive with a chief of staff and two assistants — someone who still personally answers investors, still gets pulled into hiring, and whose week has been taken over by other people’s needs. The complaint he arrived with was “I have no time to think”, which in our experience is the only complaint CEOs actually have.","The real damage is not the lost hours, it is what the hours cost: every decision gets made in the eleven minutes between two meetings, on whatever information happened to be in the room. Meetings entered cold. Commitments made out loud and remembered by nobody. Board preparation eating a weekend a quarter. Three hundred emails a day of which twelve matter, so the twelve are found late. None of that is a paperwork problem — it is a company being run on whatever its founder can hold in his head at the time."],machinery:["Holding the state of every relationship the company runs on: what was last agreed, what is still open, what was promised and by when","Making sure nothing that needs the founder reaches him late, and nothing that does not reaches him at all — with the reason attached either way","Watching the company’s own numbers for what changed, against what was expected, rather than reporting where things stand","Assembling the board pack from those same sources, in the fixed structure","Watching named competitors, the market and relevant regulatory movement, continuously","Having the material for a decision together before the meeting rather than after it"],judgement:["Every decision","Strategy","People","What the company is for"],builds:[{name:"The commitment record",text:"Everything the company agreed to, to whom, by when — gathered from the conversations where it was actually agreed rather than from anyone remembering to write it down. Founders make a great many promises out loud and remember perhaps half, and the half they forget is the half that damages a relationship."},{name:"The state of every relationship",text:"The most valuable thing on this list. Before any meeting: what was last agreed, the status of it, what is still open, the likely ask, the relevant numbers. Not a summary of a thread — the standing state of that relationship, kept current whether or not anyone asked. Walking into a meeting knowing what was promised last time changes what happens in it. This alone justified the engagement."},{name:"The change watch",text:"The company’s own numbers, watched for what moved, by how much, against what was expected. Not another screen of charts. A CEO does not need another screen of charts; they need something that has already noticed."},{name:"What reaches you, and why",text:"The company generates far more that wants the founder’s attention than the founder has attention. So something decides, and shows its reasoning: nothing is deleted, nothing is auto-replied, nothing is hidden, and what was set aside stays visible and open to review. A CEO who suspects the system is hiding something will check everything, and then it is worth less than nothing."},{name:"The outside watch",text:"Named competitors, the market, and the regulatory movement that will reach your field before it reaches your inbox. This is the work every founder intends to do and none of them has an afternoon for."},{name:"Board pack assembly",text:"Fixed structure, current numbers, last quarter’s commitments and their status. A weekend becomes a morning — and the morning goes into the narrative, the part that used to get an hour at the end."}],stops:{title:"It never decides and it never speaks as you.",text:["No external communication is generated in your voice — not to investors, not to staff, not publicly. A CEO whose words can be generated has a problem that is hard to reverse: the moment it becomes known internally, every message they send is read with a question attached.","It never recommends a course of action on anything strategic. It assembles what is known, marks what is not known, and stops. The temptation to build an AI advisor for a lonely founder is strong, and what comes out is confident, plausible and cut off from anything the system could actually know about the company. And nothing is sent automatically from that mailbox. Everything waits for you."]},proof:"Commitments kept, rather than discovered later by the person you made them to. Meetings entered knowing what was last agreed. Hours of board preparation. And the one that was actually asked for at the start: hours per week of uninterrupted thinking time, which you can count in a calendar and which was near zero.",refuse:"Any version of an AI advisory board, strategy generator or decision recommender. Also anything that generates the CEO’s voice for external use. Both were asked for. Both refused.",cost:"Fifteen minutes each morning, for the first month, checking what the system decided did and did not need you. After that, nothing.",quotes:[{text:"Ninety people, three hundred emails a day, twelve of which matter, and no hour anywhere that belonged to me. The pre-meeting brief is ninety seconds of reading and it changed what happens in the meetings, because I now walk in knowing what I promised last time. He would not build anything that writes in my voice for external use and he explained what happens internally once people suspect it, which I had not thought through. Nothing auto-sends from my mailbox. I went from effectively zero hours a week of thinking time to about ten.",name:"Founder-CEO, ~90 staff"}]},{slug:"volunteer-orgs",title:`AI for a Verein: grant applications in 3 hours — ${e.brand}`,metaDescription:"Every reusable fact about your Verein in one current file, reshaped into each funder’s form. Applications in about three hours instead of two days. Free tools only.",label:"Non-profits",headline:"Grant applications in three hours instead of two days, on free tools.",story:["A registered Verein — around 40 active volunteers, one part-time paid coordinator, funded by a mix of grants, membership fees and donations. The coordinator is doing the work of three people on 20 hours a week, and the board wanted that fixed before the next funding round.","The biggest problem is grant applications. Each funder wants the same information in a different structure — organisational description, project plan, budget, impact evidence, previous funding — and each application takes two full days. Those days come out of the delivery work, which is the whole point of the organisation. Behind that: rota coordination across 40 volunteers, membership admin, donor thank-yous and the annual report."],machinery:["Keeping the reusable facts current: mission, history, structure, staffing, finances, past projects, impact figures","Reshaping those facts into each funder’s required structure and word limits","Holding every deadline, reporting obligation and outcome across every application the organisation has ever made","Keeping forty volunteers covered without one person holding the whole rota in their head","Keeping the membership side alive: joins, fees, lapses, Beitragseinzug, and the donors who were never thanked","Collecting activity data as it happens, so the impact report is not archaeology"],judgement:["What the organisation is for","Which funder to approach and what to promise them","Every claim about impact","Your relationships with the volunteers"],builds:[{name:"The core document",text:"Every reusable fact about the organisation, written once, kept current, with a source for every number. The single most valuable thing we built, and it is essentially a well-organised text file."},{name:"The application drafter",text:"You paste in a funder’s questions and word limits. Out comes a draft built from the core document. Two days becomes about three hours, and every claim traces back to something in the core — so nothing gets invented under deadline pressure, which is exactly when organisations invent things."},{name:"The deadlines diary",text:"Application deadlines, reporting deadlines, and what was promised to whom. Missed reporting is how small organisations lose funders quietly."},{name:"The rota",text:"Availability in, shifts out, gaps visible early enough to do something about them. It was the coordinator’s largest weekly time sink, and more importantly it lived entirely in her head — which is a real risk in an organisation where the paid role turns over every few years."},{name:"The activity log",text:"Thirty seconds after each session: what happened, how many people, anything notable. A year later the impact report is written from real records instead of a panicked reconstruction in January."}],stops:{title:"No impact claim is ever generated, and no message to a funder is sent automatically.",text:['Every number in a grant application comes from the activity log or the accounts. If the log does not support it, the application says so. Overstating impact to a funder is fraud, it happens by accident under deadline pressure, and a fluent writing tool makes that accident easier — so the drafter is built to refuse. Where evidence is missing it writes "We do not yet measure this" and leaves the line for a person.',"Nothing is written about a beneficiary. Where the organisation works with vulnerable people, no personal data enters any external tool at all. Aggregate counts only. And everything must run on free or near-free tools and be operable by whoever holds the role in two years — anything that needs a subscription or a specialist will be abandoned."]},proof:"Hours per grant application. Applications submitted per year — which roughly doubled, and that is the entire economic point. Reporting deadlines met. Coordinator hours spent on admin versus delivery. Whether the activity log is still being filled in after six months.",refuse:"When an organisation wants a website, a CRM and a donor platform. That is a different project with an ongoing cost they cannot carry, and it will be abandoned within a year. A well-kept spreadsheet and a documented process outlive most systems built for organisations like this.",cost:"Thirty seconds after each session to fill in the activity log. Keeping the core document current when something changes. Nothing that costs money every month.",quotes:[{text:"A grant application took two full days and those days came out of the work the Verein actually exists to do. Everything reusable about us now lives in one place and gets reshaped into whatever structure a funder demands, so it takes about three hours. We doubled the number of applications we submit, which is the entire economic point. He built it so that if the evidence is not in our activity log the application says we do not measure it, rather than letting me improvise a number at midnight before a deadline.",name:"Coordinator, registered Verein, ~40 volunteers"}]},{slug:"research",title:`AI for researchers: grant proposals in ten days — ${e.brand}`,metaDescription:"Reusable proposal text reshaped to each call, a supervision record, literature screening and figures you can reproduce. It never invents a citation.",label:"Research",headline:"Two professors went from almost no research time to eight to twelve hours a week.",story:["Two quite different people who share a calendar problem. The professor: nine SWS of Lehrdeputat, between four and fifteen doctoral candidates, a Prüfungsausschuss, a Berufungskommission and the Fakultätsrat, six to ten manuscripts reviewed a year unpaid, and two or three grant proposals because the chair runs on Drittmittel. They were hired for their research and they do research on Sundays, if at all. And the doctoral candidate: year three of a WissZeitVG contract that ends in year four, 900 unread PDFs, three written chapters that no longer agree with each other, and an analysis that cannot reproduce its own figures.","For professors it is the proposal. A DFG Sachbeihilfe needs the state of the art, preliminary work, the work programme, budget justification, the CV, the publication list in the DFG’s own structure, a data management plan, an ethics statement and equal opportunity measures. Perhaps sixty per cent of that text already existed, in three previous proposals, in slightly wrong formats — and it gets rewritten anyway, over five weeks of evenings and weekends, because finding the old version feels harder than retyping it. For candidates it is six hundred abstracts to screen, and later the worse question: which version of the analysis, on which version of the data, produced Figure 3?"],machinery:["Screening literature: collecting everything new in a defined field and sorting it by relevance to a stated question","Cleaning up a reference library: removing duplicates, repairing details, checking every reference against its official record","Reformatting a publication list into DFG, ERC, NSF, Europass or a university’s house structure","Keeping the reusable proposal text current and reshaping it to a call’s structure and page limits","Tracking calls, Zwischenberichte, Abschlussberichte, review commitments and exam dates","Keeping the supervision record for each doctoral candidate","Checking appointment applications for completeness against the published formal criteria","Keeping the reproducibility record: which data, which version of the analysis, which figure"],judgement:["The research question. The hypothesis. The interpretation","Whether a result means anything","The assessment of a person — in a reference, a viva, a Berufungsverfahren","What to review, and what a review concludes"],builds:[{name:"The proposal core",text:"One maintained store: the CV in every format ever demanded, the publication list, the group description, infrastructure, the preliminary-work paragraphs for each research line with their figures and citations, past project outcomes, the data management plan template, the equal opportunity measures. Every item dated and sourced. About two weeks to build, mostly pulling text out of three old proposals, and it is the last time those paragraphs are ever written from nothing."},{name:"The proposal skeleton",text:"You give it a call’s structure, headings and page limits. Out comes a skeleton with the core material already placed at roughly the right length, and every section that needs original thought left empty and labelled. Five weeks becomes about ten days, and almost all ten go into the work programme — the part that gets funded."},{name:"The supervision record",text:"One private file per doctoral candidate: what was agreed, what happened, milestones against the Betreuungsvereinbarung, obstacles raised. Ninety seconds of dictation after each meeting. The piece we would install first if we could install only one — because meetings currently begin with both people trying to remember, reference letters two years later are written from a blank page, and when a candidate is quietly in trouble the record shows it four months before anyone notices in conversation."},{name:"The literature screen",text:"For candidates: six hundred abstracts checked against inclusion and exclusion criteria that are written down first. Every decision recorded with the criterion that produced it, every borderline case flagged for you. For systematic reviews this follows PRISMA and produces the flow-diagram numbers as a by-product."},{name:"The reproducibility record",text:"Which data, which version of the analysis, which software setup, which output. Every figure carries the exact command that made it. Set up in an afternoon in year one, and worth a month in year four."}],stops:{title:"It never generates a citation, and never summarises a paper you will cite.",text:["Citations come from your reference manager and are checked against each paper’s official record. Nothing that produces prose is allowed to produce a reference, ever, under any framing. Invented references are the most common and most destructive failure of language models in research, and a tired author at 23:00 cannot spot them because they look exactly right. Screening a thousand abstracts to find forty papers is routine work; reading those forty is the job — so the screen gives you titles, abstracts and links, never a summary presented as good enough.","No manuscript under review touches an external service: peer review is confidential and a manuscript is unpublished work belonging to someone else. The system never writes the argument, the hypothesis or the interpretation. It never ranks candidates in an appointment procedure — a Berufungsverfahren is legally reviewable, documented, and subject to the AGG; we have refused this twice. No data is invented, no figure generated, and no cleaning happens silently: raw stays raw. Every engagement ends with a one-page document you keep, naming which tasks used an AI tool and which funder and publisher disclosure rules apply."]},proof:"Days from a call’s announcement to a submitted proposal: typically five weeks down to about ten working days. Proposals submitted per year. Supervision meetings with a written record: from occasional to all of them. Figures reproducible with a single command: all of them. And the only one anybody cares about — hours per week available for research, which for both professors went from close to zero to between eight and twelve.",refuse:'When someone wants a paper generator — asked twice, phrased as "a first draft of the introduction" and "just the related work section". The related work section is where you show you have read the field. Also when a department wants per-person publication metrics, which is surveillance in a bibliometric costume. And when a doctoral candidate needs a supervisor rather than a system, which is the saddest version.',cost:"Two weeks of pulling text out of old proposals to build the core, once. Ninety seconds of dictation after each supervision meeting. And the discipline of reading the forty papers the screen found, which was always the job.",quotes:[{text:"Sixty per cent of every proposal already existed, in three earlier proposals, in slightly the wrong format, and I retyped it every March because finding it felt harder. Two weeks of extraction and I have not written those pages from nothing since. A DFG submission that took five weeks now takes about ten working days and nearly all of those days go to the work programme, which is the part that gets funded. He would not let anything generate a citation — references resolve by DOI or they do not appear — and given what I have seen happen to colleagues, that rule is the reason I let him near any of it.",name:"Professor (W3), natural sciences"},{text:"Year three, nine hundred unread PDFs, three chapters that no longer agreed with each other, and forty minutes with my supervisor every six weeks. The screening pipeline got six hundred abstracts down to the forty I actually had to read, and it recorded which criterion produced every decision. The reproducibility setup took an afternoon and I now know which script version made which figure, which I understand is a boring sentence and it saved me in my defence. He also told me, kindly, that what I really needed was a supervisor, and he was right.",name:"Doctoral candidate, humanities"}]}]},how:{title:"How the consulting work runs, step by step.",steps:[{title:"First: we learn your business.",text:"How you win work, where the money leaks, what your people spend their days on, and what you have quietly stopped believing is possible. Not a workshop, not a questionnaire. We sit in the building and ask questions."},{title:"Then: we map what AI opens, and where it stops.",text:"One page. On one side: the services you could offer, the speed you could reach, the costs you could cut. On the other: what stays with your people, because your name, your judgement or your relationships are on it. Read back to you, and you approve or reject each line before anything is built. That page is the plan."},{title:"Then: we prove the first ideas live.",text:"In your office, with your data, in your own accounts. Two or three ideas from the page get tested. The ones that work stay. The ones that fail cost you an afternoon and teach you something."},{title:"Last: your team takes over, and we decide what is next.",text:"The people who will run what works learn to change the rules without us, and each system gets a named owner on your side who has already changed one. Then we look at the page together and decide whether we take on the Head of AI role for the months ahead."}],termsTitle:"How it is priced and how it ends.",terms:["A fixed price for the engagement, quoted in writing after the free first call. One invoice, no day-rate meter, no expenses.","The Head of AI role is monthly, and you can stop with one month’s notice, any month, without giving a reason.","Model and cloud usage is billed to your own accounts, at cost. We never resell it and we never mark it up.","Building the larger systems the engagement finds is quoted separately, per system, after we have seen the work. We never quote a build before that.","If we conclude early that there is nothing here worth the money, we say so, we stop, and we bill only for the days already spent."]},offers:{title:"Three ways to work with us.",businessLabel:"For a business",individualLabel:"For an individual",items:[{name:"Consult",text:"We work out what AI changes for you and what it does not, and put it on one page you can act on.",business:"We learn how you make money and where you are stuck, go through the week with the people who actually do the work, and mark where AI opens something new for you — and where it must stop, because your name, your judgement or your relationships are on it. You get one page, read back to you line by line, and you approve or reject each line before anything is built.",individual:"You bring the question — a decision, a plan, an idea, the next step in your work. We bring what AI can and cannot do about it, in plain language, and a straight recommendation you can act on the same day. One session, or a few.",asks:"Access to your business and your leadership, in a shape we agree with you first."},{name:"Enable",text:"We put AI to work in your hands and leave you able to run it without us.",business:"Written rules for what may and may not be pasted into anything, the tools chosen and configured on your own accounts, your team trained on your own documents, and a named owner on your side for every system who has already changed a rule in it. This is also the Head of AI role when you want it standing: direction, experiments, tool decisions in writing, and the expert in the room when a client or an investor asks about AI.",individual:"Your own tools, on your own accounts, set up for what you actually do — and you learn to work with them at your own pace, on your own material. That includes teaching a child how this works and where it goes wrong, at their level, with the house rules to go with it.",asks:"A place at the table when AI is decided, and access to the people whose work it touches."},{name:"Build",text:"When the answer is a thing rather than a habit, we build it.",business:"Systems that run on their own, on your own material, for everyone whose work touches it — quoted per system after we have seen the work, never before. It runs in your accounts, under your logins, with your keys, and the code sits in your repository. Each one ships with a written handover, because the point is that it keeps running whether or not we are still here.",individual:"A prototype you can put in front of a co-founder or an investor, a tool you use every day, the first version of the platform behind the company you are starting. Quoted after we have understood it, built in your accounts, and yours from the first line of code.",asks:"The people who do the work, for the hours it takes to get the detail right."}]},team:{path:"/for-businesses/",label:"For businesses",title:`AI for your business — ${e.brand}, AI consulting in Berlin`,metaDescription:`We consult, we enable, and we build what has to be built. ${e.brand} brings a senior AI expert into companies, startups, teams and research groups of any size or field. Everything runs in your accounts, and every decision stays with your team.`,headline:"The AI expert your business is missing.",intro:["This page is for the person who runs the place, whatever the place is: a company, a startup, a department inside a larger one, a practice, an office of any trade, a research group, a team of any kind. You can see that AI is changing your field. You have no room for an AI department, and no time to find out by trial and error which of it matters for you.","We become that expert. Consulting inside your business to start, then the Head of AI role on retainer for as long as it pays off. We bring the direction, the ideas and the experiments, your people bring the knowledge of the business, and every decision stays with you."],offersTitle:"Three ways to work with us.",dayTitle:"What the Head of AI role covers.",dayIntro:"A running list, in the order it usually comes up.",day:["Agents that run without anyone starting them: work that used to wait for someone to have a free hour, happening continuously on your own systems","A new experiment most weeks: a service you could sell, a process you could halve, a tool worth a real test","Which AI tools to trust with your data and which to refuse, decided for you, in writing","Client pitches, tenders and grant applications that need AI in them, and need it to be credible","What your competitors and your field are trying, and which of it is worth copying","Questions from staff, answered at their desk rather than in a workshop","The written rules: what AI may and may not do in your business, kept current","For research groups: which models can do what today, which experiments are worth a PhD student’s month, and where the science must stay human"],staysTitle:"What stays with your team.",stays:["Every decision","Every signature, grade, valuation and diagnosis","Every client, patient, student and colleague relationship","The choice to stop any month"],newFieldTitle:"A field we have never seen.",newField:"A manufacturer, a logistics group, a private clinic, a fund. We have not worked in every sector. In every field so far the engagement has run the same way: we learn the business, we map where AI opens something new and where it must stop, we run the first experiments. What we build changes completely from field to field. How we find out has not had to — and if your field turns out to be the exception, you hear that early rather than at the end.",continuityTitle:"A small company, on purpose — and nothing that stops with us.",continuityIntro:`${e.brand} is a small company built around one senior AI expert, by design. You get the person who built the systems, at your table, with no account manager between you and the work and no junior learning on your data. That is only safe if nothing important depends on us — so it does not.`,continuity:[{title:"Everything is yours from day one.",text:"Every system runs in your accounts, under your logins, on your infrastructure. The code sits in your repository. The API keys are yours and billed to you directly, so you can see and cap what they cost. We hold no credential you cannot revoke in an afternoon."},{title:"Every system gets a written handover.",text:"Written the week the system is built, not the week we leave: what runs where, which service does what, how to change the rules, how to switch it off, what breaks if you do, and what to look for when something looks wrong. Written for the person on your team who will own it, and tested by having them use it while we watch."},{title:"A named person on your side owns each system.",text:"We do not hand over to “the team”. Before anything goes live, one of your people is trained on it, has changed a rule themselves, and is named in the handover as its owner."},{title:"Response times, in writing.",text:"Same working day for anything that is broken, two working days for everything else, and a named window each week when you know where to find us. If we are away for more than a week, you get the dates in advance."},{title:"If we stop, nothing stops.",text:"No system needs a licence, account, server or subscription of ours. If we disappeared tomorrow, everything we built would keep running and your named owners could keep changing it. That is the test we design against, and you can put it in the contract."},{title:"We work on a mandate, not as staff.",text:"The Head of AI role is a mandate with its own deliverables, its own tools and several clients — not an employment relationship, not instruction-bound work, and not integration into your organisation. If your finance or HR function wants that confirmed in advance, we will say so in the contract and we are happy to have the status formally determined first."}],notUsTitle:"Where we are not the right supplier.",notUs:["We do not run a 24/7 on-call rota and we do not hold your production systems for you. If you need an operations team with a pager, you need a managed-service provider, and we will say so on the first call.","We are not certified to ISO 27001, SOC 2 or TISAX, and we do not run a security team or a penetration-testing programme. If your procurement requires certification, we are not the right supplier and you will hear it before you spend time on us.","We take on a small number of clients at a time. When we are full, the line at the top of the home page says so.","We will not build anything that takes a decision, a diagnosis, a valuation, a grade or a signature away from a person. We have turned down work over it, and we would turn down yours."]},individuals:{path:"/for-individuals/",label:"For individuals",title:`An AI expert for one person — ${e.brand}`,metaDescription:"For anyone who could use an AI expert on their side without running a company: a decision, an idea, a company to start, a skill to learn, a child to teach. Consulting, hands-on help and building, in plain language, at a fixed price agreed in writing. The first conversation is free.",headline:"An AI expert on your side, for the thing in front of you.",intro:["Most of what is written about AI is written for companies. Most of the decisions it could help with are made by one person: what to do with a large sum of money, whether an idea is worth a year of your life, how to start the company you keep talking about, which of your skills to invest in next, what to tell your child about a technology that will shape their working life.",`${e.brand} gives you the same expert a company gets, sized to one person. You bring the question. We bring what AI can and cannot do about it, in plain language, with no product of ours to sell you — and where it can help, we make sure you leave able to use it yourself.`],lanesTitle:"Three ways to work with us.",recordTitle:"Who has already come through this door.",recordIntro:"People who came without a company behind them, grouped by what they came with.",record:{"job-seekers":"Applications and interviews for people who had stopped opening the replies. Most of them are in jobs found this way.",athletes:"Semi-professionals who needed a reel a scout could open the same evening, and a training log they actually kept.","home-buyers":"Fewer flats, not more: a shortlist that matched the real criteria, and the documents read before the viewing rather than after.",teachers:"Marking and report season cut to evenings. The tool finds the evidence; the teacher gives the grade.",coaches:"One-person studios. For three of the five, the honest answer was a booking system, not AI, and we said so.","online-shoppers":"The smallest job on this list. Subscriptions cancelled and returns made in time paid for the fee within a month."},runsTitle:"How it runs.",runs:["You book a free thirty-minute call or write to us. No preparation; a few sentences about what you are dealing with is enough.","We tell you honestly whether AI changes anything here. Roughly one time in three the answer is that it does not, and you leave with a recommendation instead of a proposal.","If it does, you get a fixed price in writing before anything starts: for a session, a series of them, or a build. No meter running.","We meet on video, or in person in Berlin. Everything we set up runs in your own accounts and on your own devices, and stays yours."],staysTitle:"What stays with you.",stays:["The decision. We lay out the options and what AI can find out about each of them. You choose.","Your money. We are not financial, legal or medical advisers, and we say so the moment a question crosses into that ground.","Your data. Nothing of yours lives on anything of ours.","The skill. You leave able to do the next one without us, if that is what you want."],refuseTitle:"What we will not do.",refuse:["Tell you which house to buy, which investment to make or which contract to sign. We show you how to find out more, faster, and how to check what a model tells you before you rely on it.","Do a child’s homework, or leave a child alone with a chatbot. We teach how it works, where it is wrong, and how to use it well — with the adult in the room.","Sell you a subscription, a course or a platform of ours. There is none.","Take on a question where AI adds nothing. You hear that in the first call, for free."]},principles:{title:"Three promises.",items:[{title:"Every decision stays with you.",text:"AI prepares, drafts, sorts and proposes. The decision, the diagnosis, the grade, the valuation and the verdict stay yours. We refuse to build the button that would take them away, and we have turned down work over it."},{title:"We say no out loud.",text:"If there is too little of the work, if every case is different, or if a calendar would fix it, you hear that instead of a proposal. It has cost us projects, and it is most of the reason clients introduce us to other owners."},{title:"Nothing depends on us that your team cannot run.",text:"Everything runs in your own accounts, under your own logins, with your own keys. Each system gets a written handover and a named owner on your team who has already changed a rule in it before it goes live. Nothing needs a licence, server or subscription of ours. If we stay on as your Head of AI, it is because there is new ground to take, never because a tool would stop without us."}]},about:{eyebrow:`About ${e.brand}`,title:"Practical AI, on your side.",text:[`${e.brand} is a Berlin company that puts a senior AI expert on your side — for companies, teams and research groups of any size or field, and for single people with a decision, an idea or something to learn. Most AI consultants either sell you a platform or automate your paperwork. We do something else. We look at your situation the way a new managing director would in their first month, ask what AI makes possible for you that was not possible a year ago, and test it with you until we know. Most people who can build with AI do not understand a business, and most people who understand a business cannot build. We do both, and we tell you plainly when AI will not pay off for you.`,`${e.brand} is owned and led by ${e.name}. Years of professional engineering behind the company, spent building AI systems in production — the kind other people depend on, that survive an audit, a handover and colleagues who never asked for the tool. That experience is what ${e.brand} applies to businesses small enough for one room and one decision-maker: practical advice in plain language, tools built for your business rather than for the technology, and an owner who takes personal responsibility for every project from the first call to the handover.`]},testimonials:{eyebrow:"What clients say",note:""},faq:{eyebrow:"Common questions",title:"Common questions.",allLabel:"All questions",items:[{q:"Who actually does the work?",a:`${e.brand} is a small company, and its owner, ${e.name}, leads every engagement personally: the person you speak to in the first call is the person who sits at your table, sets up the tools and does the teaching. Nothing is handed to a junior. Behind that: years of professional engineering, building AI systems in production that other people depend on.`},{q:"I am one person, not a company. Is this for me?",a:"Yes, and most of the people we have worked with came this way, none of them running a company at the time. You bring a question — a decision, an idea, a company to start, something to learn, a child to teach — and you get a session or a few with someone who does this for a living, in plain language, at a fixed price agreed in writing before anything starts. The first conversation is free either way, and if AI does not help with your question, you hear that in it. The page for individuals sets out how it runs."},{q:"You have a full-time job. How does that work?",a:"Fairly asked, and the answer is on the table before you ask it. Our owner holds a full-time engineering role building production AI, and that role is where most of the production experience behind this site comes from — it is the reason we can tell you what survives an audit rather than guessing. It also means our capacity is real and limited: we take a small number of clients at a time, and the shape of an engagement — which days, on site or on video, over how many weeks — is agreed with you in writing after the first call and before there is a contract. We will never tell you a day is available and then move it. If what you need is more than we can carry, you hear that before you spend money, not after."},{q:"Is our data safe with you?",a:"Yes, and for regulated work it is the first thing we design, not the last. Everything we build runs in your own accounts, under your own logins, with your own keys — we are not a hosting provider and we hold no credential you cannot revoke in an afternoon. Before we see anything: a mutual NDA, a data processing agreement under Art. 28 DSGVO, and a one-page scope naming exactly which systems we get access to and for how long. For law firms there is a separate confidentiality undertaking in Textform under §43e BRAO, with express instruction on the criminal consequences under §203 StGB. No training on your content, names removed wherever data has to leave your systems, and a complete record of who did what. Where a workflow cannot meet those conditions, it does not get built. The security page sets all of this out in full."},{q:"What happens after we get in touch?",a:"We talk for thirty minutes, free, with no preparation on your side. You describe your business; we tell you honestly where AI could change something for you, where it would not, and what it would involve. If it makes sense, you receive a written proposal with a fixed price. If it does not, you leave with a clear recommendation instead — which is roughly what happens one time in three."},{q:"Can you take the Head of AI role for us?",a:"Yes, that is the usual shape. After the consulting work we take the role on a retainer: direction, experiments, tool decisions in writing, your AI use policy kept current, leadership briefings, and a named window every week your team can rely on. Monthly, and you can stop with one month’s notice any month. Nobody on your side needs technical knowledge: you explain the business in your own words and everything technical stays our problem."},{q:"We already have IT. What do you do that they do not?",a:"IT keeps the systems running. We ask a different question: what could this business do with AI that it cannot do today, and which of those ideas survives a real test? Then we run the tests with your people. Most IT teams are glad someone finally does that. We work with them, not around them — and if your IT team wants to own it, better still: we spend the first weeks with them, they keep the systems, and you stop paying us sooner."},{q:"We already use ChatGPT, or we have Copilot. Why would we need you?",a:"Good — that tells us your people are willing. It also usually means company material is sitting in a tool nobody approved, with no record of what went in. A licence is not a capability. Copilot is good at the sentence in front of you; it cannot see that your contracts arrive by email and get lost, that seven quotes need normalising before they can be compared, or that every deadline in your business lives inside a document. Those are not writing problems. We work on the shape of the work, and on the written rules for what may and may not be pasted into anything."},{q:"Could we not just hire an AI engineer?",a:"You could, and if you can already specify the role you probably should. Most businesses at this stage cannot — and an engineer without a brief builds what they find interesting. Take the consulting work first. If the answer is “hire someone”, we will say so, help you write the job description, and be glad to lose the retainer."},{q:"Will the tool make decisions for us?",a:"No, and that is the point of how we build. The advice stays with the partner, the valuation with the agent, the direction with the founder, the priorities with the head of department. The tool takes over the repetitive work and prepares the material. Your people decide. We have refused to build the “accept all” button more than once."},{q:"You have never worked in our field. Does this still work?",a:"Usually, yes. A manufacturer, a logistics group, a private clinic. In every field so far the engagement has run the same way: we learn the business, we map where AI opens something new and where it must stop, we run the first experiments. What we build changes completely from field to field. How we find out has not had to — and if your field turns out to be the exception, you hear that early rather than at the end."},{q:"Our people will resist this.",a:"Some will, and usually the ones who are right to. Resistance is almost always one of two things: fear about the job, or a previous tool that made the work worse. So we build only where the person doing the work agrees the work is repetitive, we never build anything that reports on individuals, and we refuse to build the button that takes the decision away. The team-leaders example on this site is a system that organises what a manager observed and explicitly never rates anyone — we were asked for the version that watched people, twice, and said no both times."},{q:"How would we prove the return?",a:"We agree the numbers before we start. At the beginning we write down two or three measurements with today’s values — hours on a named task, days from A to B, the count of the thing that keeps going wrong. At the end we measure the same things again on whatever we built. If they have not moved, that goes in the write-up too. And the honest arithmetic is simple: count the task for one week, multiply by what an hour of that person’s time is worth to the business, then halve it. If that number is small, we will tell you this is not worth buying."},{q:"Are we locked in to you?",a:"No, and it is designed out rather than promised. Everything runs in your accounts, under your logins, with your API keys billed to you at cost. The code sits in your repository. Each system has a written handover and a named owner on your team who has already changed a rule in it. Nothing needs a licence, account, server or subscription of ours. If we disappeared tomorrow it would all keep running — put that in the contract and we will sign it."},{q:"What if we want to stop?",a:"The retainer ends with one month’s notice, any month, without a reason. Everything we built keeps running: your accounts, your logins, your repository, your keys. You get the handover for each system and, on request, a full export of the logs and written confirmation that we hold nothing of yours. The consulting work has a natural stopping point built into it — at the end you decide whether anything continues, and you keep the plan and the working systems either way."},{q:"What if AI is the wrong answer for us?",a:"Then you hear it in the first conversation, before you have committed to anything. It happens often: what looked like an AI problem turns out to be a process nobody owns, or a tool your team already has and does not use. We say so, and we say it early. If we only work it out once we are inside the business, we say it then, we stop, and we bill only for the days already spent."},{q:"Do we have to be in Berlin?",a:"No. The first conversation is a call either way, and the Head of AI role runs partly over video once we know your business. Clients so far include Leipzig and Brandenburg. Berlin simply makes the on-site part easier to do in person."},{q:"How much of our time does this take?",a:"Most of it is in the consulting work: time in the building with us, plus an afternoon of training for the people who will own what we build. After that, the Head of AI role costs your leadership a short meeting a week and your team the occasional hour to try something new. What we put in place takes seconds to use: ninety seconds of dictation after a site visit, one photograph of an invoice."}]},contactSection:{eyebrow:"Get in touch",title:"Tell us what you are dealing with.",lead:"Thirty minutes, free, no preparation. We tell you honestly where AI could change something for you, and where it would not.",form:{name:"Name",email:"Email",subject:"What is this about",subjects:["Our business or startup","Our research group or institute","Just me — a personal question or project","A talk or a workshop","Something else"],message:"Message",messageHint:"A sentence about your situation is plenty. No preparation needed.",emailHint:"So we can reply.",send:"Send message",sending:"Sending…",reply:"We reply within one working day.",success:"Thank you. We will get back to you within one working day.",error:"That did not go through. Please email us instead.",note:"Prefer not to use a form? Book a call or email us directly."}},evidence:{eyebrow:"Evidence",title:"What we have actually built.",items:[{name:"A contract system for a commercial law firm",text:"Contracts filed and versioned the moment they arrive, every deadline in the diary, and each incoming draft opening in Word with tracked changes where every suggestion carries its reason. There is no accept-all button — we were asked for one and refused.",link:"/work/lawyers/",linkLabel:"Read the case"},{name:"A production contract-lifecycle platform for a corporate legal team",text:"Conversational intake, an in-app agentic copilot, and a Microsoft Word add-in producing native tracked-change redlines. Every AI action runs as the signed-in user, so it inherits the same permissions and the same audit trail as a human request, behind a confirm gate that pauses every change for approval. It replaced a commercial vendor costing about €70,000 a year. Built by our owner as an in-house AI engineer — the work that taught us what survives an audit.",link:"linkedin",linkLabel:"The record, on LinkedIn"},{name:"A customer-service assistant live across six markets",text:"About 45% of first-line contacts resolved without a human, with prompts and model configuration versioned so a change ships by moving a label rather than redeploying. Also in-house work, at a Berlin company.",link:"linkedin",linkLabel:"The record, on LinkedIn"},{name:"Client work across many fields",text:"Startup founders and company directors, heads of department inside larger companies, research groups, architecture practices, marketing agencies, a law firm, a real estate company and an NGO.",link:"/work/",linkLabel:"All examples"}],note:"We say which is which. The client engagements on this site are separate from the systems our owner built as an employee, no client’s material has ever touched another engagement, and we do not publish a number we cannot source."},founder:{path:"/about/",label:"About us",title:`What stands behind ${e.brand}`,metaDescription:`Professional engineering behind the company, building production AI systems other people depend on. What you are actually hiring when you hire ${e.brand}.`,headline:"What stands behind Dinobridge.",intro:["Most AI projects fail for one of two reasons. Either the person who understood the business could not build, so the thing that got built solved the wrong problem — or the person who could build did not understand the business, so it solved a real problem nobody had.",`Years of professional engineering sit behind ${e.brand}, spent building AI systems in production: the kind other people depend on, that survive an audit, a handover and colleagues who never asked for the tool.`,`${e.brand} is owned and led by ${e.name}, and this page is the case for why that combination is the qualification rather than a compromise.`],whyTitle:"Why that combination is the qualification.",why:[{title:"AI engineering, not prompt-writing.",text:"Retrieval pipelines, agents, model and prompt versioning, deployment, and evaluation harnesses that decide what is allowed to reach production. This is the part that separates a demo from a system your team can rely on when nobody is watching it."},{title:"Business operations.",text:"Years of it inside organisations where the AI had to work for colleagues who never asked for it, survive a handover, and answer to an auditor. That is a different discipline from making something impressive, and it is the one that decides whether a system is still in use a year later."},{title:"Regulated workflows.",text:"Contracts under confidentiality, with permissions and an audit trail as first-class requirements rather than a later phase. It is why the law-firm work starts with what may not leave the building rather than with what the model can do."},{title:"Leadership.",text:"The people who commissioned those systems were the people accountable for the function. Explaining a trade-off to a decision-maker in their own vocabulary — and being told no, and saying no — is most of the job."},{title:"Implementation.",text:"Every system described on this site was built by the person who sat in the room where the problem was described. There is nobody to hand it to."}],honestTitle:"The honest part.",honestIntro:`${e.name} holds a full-time engineering role building production AI, and that role is where most of the production experience on this site comes from — it is the reason we can tell you what survives an audit rather than guessing. It also means capacity is real and limited, and you should know its shape before we talk rather than after.`,honest:["We take a small number of clients at a time. The line at the top of the home page says whether there is room.","The shape of an engagement — which days, on site or on video, over how many weeks — is agreed with you in writing after the first call and before there is a contract. We will never tell you a day is available and then move it.","The Head of AI role is a named window every week, agreed before we start.","Client work and employed work are kept strictly separate. No client’s material has ever touched another engagement, and none ever will.","If what you need is more than that, you hear it before there is a contract. It has happened."],refuseTitle:"What we will not do.",refuseText:"Build the button that takes the decision away. Automate anything where your name, your licence or your signature is on the result. Sell you a system when a calendar, a form or a shared spreadsheet would fix it — that has cost us work, and it is most of the reason clients introduce us to other owners.",linkLabel:`${e.name} on LinkedIn`},security:{path:"/security/",label:"Security",title:`Security and confidentiality — ${e.brand}`,metaDescription:`What happens to your data when you work with ${e.brand}: what we sign before we start, where processing happens, what stays with your people, what we do not have, and what happens when we stop.`,headline:"Security and confidentiality.",intro:[`${e.brand} is a small company whose work means being given access to other people’s contracts, patient records, case files and research data. This page is the full answer to what happens to them, written before you asked.`,"If something you need is not here, write to us. We answer security questions in writing within two working days, we will complete your questionnaire, and we will mark anything we cannot answer as “no” rather than as “in progress”."],approachTitle:"Our approach, in three rules.",approach:[{title:"Your data stays in your systems.",text:"Everything we build runs in your own tenancy, under your own accounts, with your own API keys billed directly to you. We are not a hosting provider and we do not want to be one. We hold no credential you cannot revoke in an afternoon."},{title:"Confidentiality is designed first, not added later.",text:"For regulated work — patient files, case documents, children’s data, research under ethics approval — the constraints get written down before anything is designed. Some workflows do not survive that. Those do not get built, and we say so rather than working around it."},{title:"Everything is recorded.",text:"Who did what, on which document, when, and whether a person accepted or rejected it. A system nobody can audit is not deployable, whatever else it can do. This is the first thing we design, not the last."}],signTitle:"What we sign before we see anything of yours.",sign:["A mutual non-disclosure agreement.","A data processing agreement under Art. 28 DSGVO.","A one-page scope naming exactly which systems we get access to, and for how long. Access is granted by you and revoked by you at the end of each phase; we hold no standing administrator access.","For law firms, a separate confidentiality undertaking in Textform under §43e BRAO, in which we are expressly instructed as to the criminal consequences of a breach under §203 StGB, and which states whether any further person may be involved."],processingTitle:"Where processing happens.",processing:["Client systems run in your own tenancy, in the region you choose.","Where a document has to be sent to a model to be read, the provider, the region and the terms are named in the proposal and in the data processing agreement, so you can put them to your own data protection officer before anything is signed. No processing outside the EU. If a workflow would require it, you hear that before it is designed — §43e BRAO requires comparable protection for services performed abroad, and the simplest way to satisfy that is not to go abroad.","No training on your content, and no retention by a provider beyond the request.","Names and identifiers are removed wherever data has to leave your systems at all."],siteTitle:"This website itself.",siteText:"Static pages, no cookies, no analytics, no usage profiles, no application server. The site is hosted on GitHub Pages (GitHub, Inc., US) behind Cloudflare (Cloudflare, Inc., US); the contact form runs through Formspree (US) and the booking calendar through Cal.com (US), which loads only when you click it. All four are set out in the Datenschutzerklärung. They handle enquiries, not client work — no client material of any kind passes through them, and none of them appears in a client engagement.",oversightTitle:"Human oversight.",oversightText:"No decision, diagnosis, valuation, grade, verdict or signature is ever produced by a system we build. No output reaches a client, a counterparty or a patient without a person accepting it. There is no accept-all button in anything we have built; we were asked for one and refused. Every extracted fact is pinned to the page and paragraph it came from, so checking it takes seconds, and the system returns the exact text of a norm or a clause rather than paraphrasing it.",accessTitle:"Access control.",accessText:"Systems act as the signed-in user, so an AI action inherits exactly the permissions that person already has and never more. If someone cannot open a matter today, nothing we build lets them open it tomorrow. Our own access is named in the scope document, limited to the work, granted by you and revoked by you.",governanceTitle:"AI governance.",governanceText:"Every engagement produces a written AI use policy for your business: what AI may and may not do here, who decides, what is logged, and which tools are approved or refused. Under Article 4 of the EU AI Act, organisations that use AI at work must support AI literacy among the staff who use it, and national authorities have had supervisory powers since 2 August 2026. This document, and the workshop that goes with it, are how we help you meet that. It is not legal advice, and we would rather you had your own adviser confirm it.",handoverTitle:"Documentation, exit and portability.",handoverText:"A written handover for every system, produced the week it is built: what runs where, which service does what, how to change a rule, how to switch it off, what breaks if you do, and what to look for when something looks wrong. Written for the named owner on your team and tested by having them use it while we watch. On exit: the code is already in your repository, the credentials are already yours, the data is already in your systems, and on request you get a full export of the logs and written confirmation that we hold nothing of yours. Nothing needs a licence, account, server or subscription of ours.",notTitle:"What we do not have.",notText:"We are not certified to ISO 27001, SOC 2 or TISAX. We do not run a security team, a 24/7 monitoring service or a penetration-testing programme. We are one senior engineer with a written way of working, no employees and no subcontractors. If your procurement requires certification or an insurance certificate, we are not the right supplier and you will hear that on the first call rather than in week six.",contactTitle:"Security questions.",contactText:"Write to us and we answer in writing within two working days. Send your questionnaire and we will complete it — marking anything we cannot answer as “no” rather than as “in progress”."},marketingAgencies:{path:"/for-marketing-agencies/",label:"For marketing agencies",title:`AI systems for marketing agencies — ${e.brand}`,metaDescription:"AI consulting and production systems for marketing agencies: turn briefs, research, content operations and reporting into a calmer, reviewable workflow while strategy and creative judgement stay with the team.",headline:"More room for the work clients actually notice.",intro:["An agency does not need another chat window. It needs the scattered parts of delivery — briefs, research, source material, variants, approvals and reporting — to move through one dependable system.","We find the repeatable work around the creative decision, build that part into your own stack, and leave the strategy, taste and client relationship exactly where they belong: with your team."],imageAlt:"An abstract campaign workflow moving from scattered source material into a clear approved output",imageCaption:"From scattered inputs to a reviewable campaign system.",pressureTitle:"Where agency time disappears.",pressureLead:"The expensive part is rarely making the first idea. It is everything that has to happen around it, every time, without losing the thread.",pressures:[{title:"The brief changes shape.",text:"Calls, decks, emails and comments become one working brief with the open questions visible before production starts."},{title:"Research gets repeated.",text:"Audience, competitor and market material is collected with sources attached, then kept reusable instead of rebuilt for every pitch."},{title:"Versions multiply.",text:"Channel and format variants are prepared from approved source copy, with a clear record of what changed and who approved it."},{title:"Reporting starts from zero.",text:"The weekly evidence is gathered continuously, anomalies are surfaced, and the team writes the explanation rather than rebuilding the numbers."}],systemTitle:"One calm production line.",systemLead:"The first useful system is usually smaller than an “AI transformation” and more valuable than a collection of prompts.",system:[{title:"Collect",text:"Bring the brief, source files, previous work and client rules into one traceable intake."},{title:"Structure",text:"Extract the facts, constraints, audiences, claims and missing decisions; link every fact back to its source."},{title:"Prepare",text:"Generate research summaries, first drafts and channel variants only inside the rules the team approved."},{title:"Review",text:"Route every material change to a named person. Nothing publishes, sends or changes budget on its own."},{title:"Learn",text:"Keep the approved language, rejected directions and campaign evidence available for the next piece of work."}],boundaryTitle:"The line we do not cross.",boundaryLead:"AI can prepare the field. It cannot own the position.",boundaries:["No invented customer insight, performance claim, quotation or source.","No publishing, client reply or budget change without a named human approval.","No system that scores individual creatives or monitors activity.","No model trained on one client’s confidential material for another client’s work.","Strategy, taste, accountability and the client relationship stay with your people."],startTitle:"Good places to start.",startLead:"Pick one repeated hand-off with a visible cost. We map it, test it on recent work and measure the same thing before and after.",starts:[{title:"Brief intake",text:"From mixed client material to a complete working brief and a list of unanswered decisions."},{title:"Research desk",text:"Source-backed market and competitor monitoring that stays current between pitches."},{title:"Content operations",text:"Approved source copy routed into channel variants, review and version history."},{title:"Client reporting",text:"Evidence gathered on schedule, with exceptions surfaced for a strategist to explain."}],ctaTitle:"Bring us one messy hand-off.",ctaText:"Thirty minutes, free, no deck needed. Show us where the work stalls; we will tell you whether AI changes it, what should remain human, and what a useful first test would be."},lawFirms:{path:"/for-law-firms/",label:"For law firms",title:`AI in a law firm, without touching legal judgement — ${e.brand}`,metaDescription:"For managing partners, boutiques and in-house legal departments: what AI can safely take over, what stays lawyer-controlled, how confidentiality is protected under §43e BRAO and §203 StGB, and what happens to client data.",headline:"AI in a law firm, without touching a single point of legal judgement.",intro:["For managing partners, commercial firms, boutiques and in-house legal departments. Your paperwork gets faster. Your advice, your concessions and your signature do not move an inch.","Your reputation and your professional obligations are on the line, not ours. So this page answers the questions you would have to ask us, in the order you would ask them."],sections:[{title:"Why us",text:["The person who would work in your firm has built this before, in production, as an in-house engineer: an end-to-end contract lifecycle platform for a corporate legal team — conversational intake, an in-app copilot, and a Microsoft Word add-in producing native tracked-change redlines. Every AI action in it ran as the signed-in user, inheriting the same permissions and the same audit trail as a human request, behind a confirm gate that paused every change for approval. It replaced a commercial vendor costing about €70,000 a year.","That is the difference between a consultant who has read about legal AI and an engineer who has shipped it inside a legal function with an audit trail attached. It is also why the first question we ask about any workflow is “who did this, and can you show me?” rather than what the model can do."]},{title:"What AI can safely take over",lead:"Contracts as objects. Not law.",list:["Pulling contracts out of the mailbox the moment they arrive","Naming and versioning every file to one convention, permanently, with its history kept","Extracting parties, dates, term, notice periods, governing law, liability caps and auto-renewal — every field pinned to the page and paragraph it came from","The deadline diary: every date in every contract, in front of you before it matters","Comparing an incoming draft against your own playbook and marking where it differs","A first-pass markup in Word with tracked changes, each suggestion carrying its reason","Chasing the counterparty who has not returned the draft, and the internal signatory","Filing to your document system correctly, first time","Answering “where is this contract, and which version is current?” instantly"],text:["The version problem goes in the first weeks, and it is the change people notice first."]},{title:"What stays lawyer-controlled, permanently",text:["Whether a clause is acceptable. What to concede. Advice, to anyone, internal or external. Signature.","No advice is ever generated. No output is ever sent to a counterparty automatically. No clause is redrafted without a stated reason you can evaluate. There is no accept-all button — we were asked to build one and refused, and the partner who asked has said since that they would not have continued if we had built it.","Every suggestion is accepted or rejected individually, by a lawyer, in Word — your own tool, not ours."]},{title:"How confidentiality is protected",lead:"Two instruments, because German professional law requires both and only one of them is about data protection.",list:["A data processing agreement (AVV) under Art. 28 DSGVO, signed before we see anything.","A confidentiality undertaking in Textform under §43e BRAO, in which we are expressly instructed as to the criminal consequences of a breach under §203 StGB, and which states whether any further person may be involved — the answer is no, because Dinobridge is one person with no employees and no subcontractors. If that ever changes, it changes by written amendment before it happens, not after."],text:["We know §43e is a separate duty from Art. 28, and we know you have to be able to document that you selected your provider carefully. We give you the file to do that with, at the start, without being asked."]},{title:"What happens to client data",text:["It stays in your systems. Every system we build runs in your tenancy, under your accounts, with your API keys billed directly to you. We do not host your matter content, we do not copy it to our own infrastructure, and we hold no credential you cannot revoke this afternoon.","Where a document has to be sent to a model to be read, the provider, the region and the terms are named in the proposal and in the AVV, so you can put them to your own Datenschutzbeauftragter before anything is signed. No training on your content and no retention beyond the request. No processing outside the EU — and if a workflow would require it, you hear that before it is designed, because §43e requires comparable protection for services performed abroad and the simplest way to satisfy that is not to go abroad.","Where a workflow cannot meet those conditions, it does not get built. That has happened, and we said so rather than working around it."]},{title:"What is logged, and who can see what",text:["Every action: who triggered it, on which document, at what time, what came back, and whether a person accepted or rejected it. Retained for a period agreed with you, then deleted on schedule, and exportable by you in full at any time without asking us. A legal AI system without an audit trail is not deployable, whatever else it can do.","Access follows your existing permissions. The systems act as the signed-in user, so an AI action inherits exactly the rights that person already has and never more — if a fee-earner cannot open a matter today, nothing we build lets them open it tomorrow. Our own access is named in the scope document, limited to the work, granted by you and revoked by you at the end of each phase. We hold no standing administrator access."]},{title:"How a contract is actually reviewed",steps:["It arrives. It is identified, versioned, linked to its matter and its predecessor, and filed.","The summary sheet is produced, every field pinned to its source page and paragraph.","It is compared against your playbook — your own written positions — and the differences are marked.","A Word document is produced with tracked changes, each suggestion carrying its reason as a comment: which playbook position it comes from, or which risk it addresses.","A lawyer opens it in Word and accepts or rejects each change, individually.","Every one of those decisions is logged."],text:["Nothing between the first step and the fifth leaves the firm, and nothing after the fifth happens without a person."]},{title:"How hallucination risk is controlled",lead:"Four mechanisms, none of which is “we use a good model”.",list:["Nothing is asserted without a location. Every extracted fact carries a pin to the page and paragraph, so checking it takes four seconds. A fact you cannot check is worse than no fact — it looks like knowledge.","Nothing is suggested without a reason. A markup with no stated basis is unreviewable, so the system cannot produce one.","The comparison is against your own written playbook, not against a model’s idea of market standard. If a position is not written down, the system has nothing to compare with and says so.","The system never paraphrases. For norms and clauses it returns the exact text with its location, because a paraphrased provision is a liability."],text:["And structurally: there is no path from the system to a counterparty, a client or an internal recipient that does not pass through a person accepting a specific change."]},{title:"The implementation process, and what it integrates with",text:["Before anything starts: the NDA, the AVV, the §43e undertaking, and a one-page scope naming which systems we access and for how long.","Then intake and filing first — nothing intelligent. Then the summary sheet and the deadline diary, both useful within days, and the diary is the piece with the highest raw value because a missed notice period is a claim. Then the playbook: your positions, written down properly, with you. That is the hardest and most valuable part of the project, and the part most firms have never done. The first-pass markup comes last, because the playbook has to exist first and the playbook is your work, not ours. Anyone promising you a markup in the second week has never written a playbook with a firm.","It works with Outlook and Exchange, with Word as a native add-in so your people stay in Word rather than in someone’s portal, with SharePoint and Windows file shares, with your calendar for the deadline diary, and with your document management system where it has an interface. If yours has no interface, you hear that on the first call rather than in the third week."]},{title:"How quickly you see value",text:["Filing and versioning first, and it is the change people mention first. The deadline diary next, and it is the one that prevents a claim. The markup last, once the playbook exists.","Throughout, a named person in your firm owns each piece, is trained on it, and has changed a rule in it themselves before it goes live."]},{title:"What proof exists",text:["A commercial practice with two partners, and an in-house legal function of five inside a manufacturing group of about three hundred people. Both asked not to be named — role and region only, which is the norm in this sector — and both have agreed to speak to a serious prospect after a first conversation. We keep a private record of who said what.","And separately, verifiable without any client’s permission: the production contract-lifecycle platform described at the top of this page, built in-house, which replaced a vendor costing about €70,000 a year."]},{title:"What happens if you stop working with us",text:["Everything keeps running. It is in your tenancy, under your accounts, with your keys, and the code is in your repository. You get a written handover for every system — produced the week it was built, not the week we leave — covering what runs where, how to change a rule, how to switch it off and what breaks if you do. A named person in your firm has already used it while we watched.","On request, at any time: a full export of every log, and written confirmation that we hold nothing of yours. Nothing needs a licence, account or subscription of ours. If we disappeared tomorrow, your systems would run and your people could change them."]},{title:"Where we say no",text:["Bespoke, high-value, one-off negotiation work. There is no playbook there because there is no repetition, and a first-pass markup on a genuinely novel deal is noise dressed up as help.","Anything that produces advice. Anything that sends. Anything with an accept-all button."]}],ctaTitle:"Talk through one workflow.",ctaText:"Thirty minutes, free, no preparation. If your firm’s constraints make this undeployable, you hear that on the call rather than in a proposal.",disclaimer:"Nothing on this page is legal advice, and we are not lawyers. §43e BRAO and §203 StGB are cited because they govern how you may instruct us; please have your own Berufsrecht adviser confirm our undertaking before you sign it."},footer:{impressum:"Impressum",datenschutz:"Datenschutz"}};export{a as e};
